#!/usr/bin/env bash
# Regenerate ui/MED_theme_data.m31 (the built-in themes, as m31 source) from themes/*.toml.
#
#   bash scripts/gen_themes.sh          rewrite ui/MED_theme_data.m31
#
# Needs only bash and awk (the same on macOS). tests/t_theme.m31 fails when the
# generated file is out of date with the .toml files.
set -euo pipefail
cd "$(dirname "$0")/.."
out=ui/MED_theme_data.m31
files=$(ls themes/*.toml | LC_ALL=C sort)

constant_of() {   # file name -> m31 constant name
    basename "$1" .toml | tr 'a-z' 'A-Z' | sed 's/+/_PLUS/g; s/-/_/g'
}

{
    echo "// Generated by scripts/gen_themes.sh from themes/*.toml. Do not edit."
    echo "// The built-in themes, one list of source lines each; MED_theme parses them."
    echo
    printf 'pub const List<str> NAMES = ['
    first=1
    for f in $files; do
        [ $first = 1 ] || printf ','
        printf '\n    "%s"' "$(basename "$f" .toml)"
        first=0
    done
    printf '\n];\n'
    for f in $files; do
        echo
        echo "pub const List<str> $(constant_of "$f") = ["
        # one string literal per line: backslash, quote and tab escaped, CR dropped
        awk '
            { gsub(/\r/, ""); gsub(/\\/, "\\\\"); gsub(/"/, "\\\""); gsub(/\t/, "\\t");
              printf "%s    \"%s\"", (NR > 1 ? ",\n" : ""), $0 }
            END { printf "\n" }
        ' "$f"
        echo "];"
    done
    echo
    echo "/// The source lines of built-in theme \`name\` (empty when there is none)."
    echo "pub List<str> source_of(str name) {"
    for f in $files; do
        echo "    if (name == \"$(basename "$f" .toml)\") {"
        echo "        return $(constant_of "$f");"
        echo "    }"
    done
    echo "    return [];"
    echo "}"
} > "$out"
echo "$out"
